// INPUT: Google Sheets "Get rows" gives rows with keys like:
// { row_number: "2", agreement_type: "Auto Loan", governing_law: "State of Illinois", ... }

const rows = $input.all();

// Merge all rows into a single object
let data = {};
for (const row of rows) {
  Object.assign(data, row.json);
}

// Remove helper columns you don't want
delete data.row_number;

const system = "You are a loan-agreement analysis assistant. Return a plain text report with these sections:\n1. Executive Summary\n2. Loan Breakdown\n3. Borrower & Lender Analysis\n4. Observations & Risks\n5. Recommendations";

const user = "Data (attribute → value):\n" + JSON.stringify(data, null, 2);

return [{
  json: {
    messages: [
      { role: "system", content: system },
      { role: "user", content: user }
    ],
    data
  }
}];

const items = $input.all();

// Build Markdown from parsed text block
const markdownItems = items.map(item => {
  const text = item.json.text || '';
  return {
    json: {
      markdown: `### Parsed Invoice\n\n\`\`\`\n${text.trim()}\n\`\`\``
    }
  };
});

return markdownItems;
